message.content:
{
  "description": "The creature is a quadrupedal hybrid standing in profile facing right on a small patch of grassy, rocky ground, with its head turned slightly toward the viewer. It has the head, legs, paws and short tail of a spotted felid and the torso, chest and dorsal plumage of a penguin-like bird. The head is tawny-orange with dense black spotting, the body is stout with a dark gray-black back and sides contrasting sharply with a white and yellow-orange chest and belly, and the four legs are long, muscular and spotted. A single dark flipper-like wing is folded against the side of the body. The overall texture is furry on the head, neck and legs and dense, small, scale-like feathered on the back and sides.",
  "parts": [
    {
      "part": "head",
      "looks_like": "cheetah-like, tawny-orange fur with small solid black spots on the forehead, crown and cheeks, a distinct black tear-stripe running from the inner corner of each amber-brown eye down to the mouth, a black nose, white muzzle, chin and throat with white whiskers, and a slightly open mouth",
      "where": "at the anterior end of the body on top of the neck, facing right with eyes directed slightly outward toward the viewer"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, upright ears with tan outer fur, blackish rims and paler inner fur",
      "where": "on top of the head, one on each side of the crown"
    },
    {
      "part": "mane",
      "looks_like": "short, erect, spiky fur, black on the dorsal midline with tan at the base, giving a ruffled appearance",
      "where": "along the dorsal side of the neck from just behind the ears to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four long, muscular legs covered in short tan fur with large solid black spots and horizontal black bars near the lower leg, felid in shape with visible joints",
      "where": "two forelegs under the chest and two hindlegs under the hips, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "four large, broad paws with tan fur, rounded toe pads and long, curved, light-colored claws protruding from each toe",
      "where": "at the distal ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, stubby and fluffy, tan with black spots and a thick black tip with long shaggy fur",
      "where": "at the posterior end of the body, projecting from the rump"
    },
    {
      "part": "wings",
      "looks_like": "one dark gray to black flipper-like wing with a dense, pebbly, scale-like feather texture and faint darker spots, broad and paddle-shaped with a smooth trailing edge",
      "where": "folded flat against the right side of the torso, extending from the shoulder down to mid-flank and partially overlapping the right foreleg"
    },
    {
      "part": "feathers",
      "looks_like": "dense, very small, scale-like feathers covering the dorsal and lateral torso, dark gray-black with a slightly glossy, pebbled texture",
      "where": "over the back, shoulders, sides and upper rump, contrasting with the furry neck, head and legs"
    },
    {
      "part": "markings",
      "looks_like": "solid black spots of varying size on the head, legs, belly fringe and over the dark dorsal feathered area; black tear-lines on the face; a sharp color block with a white lower chest and belly, pale yellow to orange-yellow upper chest and neck, and a dark gray-black dorsal cape; black bars on the lower legs",
      "where": "spots distributed on the head, all four legs, ventral fringe and dorsal back; tear-lines on the face; color blocks covering the ventral chest/belly and dorsal back/sides"
    }
  ],
  "attached_objects": [],
  "animals": [
    "cheetah",
    "penguin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 1,
  "extra_limb_pieces": 0,
  "tails": 1
}
